  document.getElementById("btnNext").classList.toggle("gold",last);
  show("scrWin");
  if(!last&&!rec(LEVELS[levelIdx+1].id).done) setTimeout(function(){ toast("ZONE "+(levelIdx+2)+" UNLOCKED"); },900);
}

/* buttons */
function click(id,fn){ document.getElementById(id).addEventListener("click",function(){ unlock(); SFX.click(); fn(); }); }
click("btnPlay",function(){
  var i=0; for(var k=0;k<LEVELS.length;k++){ if(unlockedIdx(k)) i=k; }
  startLevel(i);
});
click("btnLevels",function(){ buildGrid(); show("scrLevels"); setState("levels"); });
click("btnBackHome",function(){ show("scrHome"); setState("home"); });
click("btnPause",function(){ if(state==="playing"){ setState("paused"); show("scrPause"); } });
click("btnResume",function(){ if(state==="paused"){ show(null); hudEl.classList.remove("hidden");
  dpadEl.classList.toggle("hidden",!isTouch); lastFrame=performance.now(); setState("playing"); } });
click("btnRestart",function(){ startLevel(levelIdx); });
click("btnQuit",function(){ buildGrid(); show("scrLevels"); setState("levels"); });
click("btnRetry",function(){ startLevel(levelIdx); });
click("btnOverLevels",function(){ buildGrid(); show("scrLevels"); setState("levels"); });
click("btnReplay",function(){ startLevel(levelIdx); });
click("btnWinLevels",function(){ buildGrid(); show("scrLevels"); setState("levels"); });
click("btnNext",function(){
  if(levelIdx<LEVELS.length-1) startLevel(levelIdx+1);
  else { buildGrid(); show("scrLevels"); setState("levels"); }
});
click("btnReset",function(){
  if(confirm("Reset all progress, stars and coins?")){ save={name:save.name,coins:0,muted:save.muted,levels:{}}; persist(); refreshHome(); toast("PROGRESS RESET"); }
});
var soundBtn=document.getElementById("btnSound2"), soundBtn1=document.getElementById("btnSound1");
function toggleSound(){ unlock(); setMuted(!save.muted); SFX.click(); refreshSound(); }
soundBtn.addEventListener("click",toggleSound);
soundBtn1.addEventListener("click",toggleSound);
function refreshSound(){
  soundBtn.textContent=(save.muted?"🔇 SOUND: OFF":"🔊 SOUND: ON");
  soundBtn1.textContent=(save.muted?"sound: off":"sound: on");
}

var nameInput=document.getElementById("inName");
nameInput.value=save.name;
nameInput.addEventListener("input",function(){
  var v=nameInput.value.toUpperCase().replace(/[^A-Z0-9 _\-.!]/g,"").slice(0,10);
  nameInput.value=v; save.name=v.trim()||"PLAYER"; persist();
});
nameInput.addEventListener("keydown",function(e){ e.stopPropagation(); if(e.key==="Enter") nameInput.blur(); });
function refreshHome(){
  document.getElementById("homeCoins").textContent=save.coins;
  nameInput.value=save.name; refreshSound();
  document.getElementById("ctrlText").innerHTML = isTouch
    ? "<b>Swipe</b> anywhere to steer<br><b>D-pad</b> bottom-right<br><b>❚❚</b> to pause"
    : "<b>Arrows / WASD</b> — steer<br><b>Space / P / Esc</b> — pause<br><b>R</b> — restart · <b>M</b> — mute";
}

/* keyboard */
window.addEventListener("keydown",function(e){
  if(e.target&&(e.target.tagName==="INPUT")) return;
  var k=e.key,d=null;
  if(k==="ArrowUp"||k==="w"||k==="W") d={x:0,y:-1};
  else if(k==="ArrowDown"||k==="s"||k==="S") d={x:0,y:1};
  else if(k==="ArrowLeft"||k==="a"||k==="A") d={x:-1,y:0};
  else if(k==="ArrowRight"||k==="d"||k==="D") d={x:1,y:0};
  if(d){ e.preventDefault(); turn(d); return; }
  if(e.repeat) return;
  if(k===" "||k==="p"||k==="P"||k==="Escape"){
    e.preventDefault();
    if(state==="playing"){ setState("paused"); show("scrPause"); }
    else if(state==="paused"){ document.getElementById("btnResume").click(); }
  } else if(k==="Enter"){
    if(state==="home") document.getElementById("btnPlay").click();
    else if(state==="over") document.getElementById("btnRetry").click();
    else if(state==="win") document.getElementById("btnNext").click();
    else if(state==="paused") document.getElementById("btnResume").click();
  } else if(k==="r"||k==="R"){
    if(state==="playing"||state==="paused"||state==="over") startLevel(levelIdx);
  } else if(k==="m"||k==="M"){ unlock(); setMuted(!save.muted); refreshSound(); toast(save.muted?"SOUND OFF":"SOUND ON"); }
});

/* touch: swipe + dpad */
var ptr=null;
window.addEventListener("pointerdown",function(e){
  unlock();
  if(e.target.closest&&e.target.closest("button,input,.lvl,.screen")) return;
  if(state!=="playing") return;
  ptr={id:e.pointerId,sx:e.clientX,sy:e.clientY};
},{passive:true});
window.addEventListener("pointermove",function(e){
  if(!ptr||ptr.id!==e.pointerId||state!=="playing") return;
  var dx=e.clientX-ptr.sx, dy=e.clientY-ptr.sy;
  if(Math.abs(dx)<20&&Math.abs(dy)<20) return;
  if(Math.abs(dx)>Math.abs(dy)) turn({x:dx>0?1:-1,y:0}); else turn({x:0,y:dy>0?1:-1});
  ptr.sx=e.clientX; ptr.sy=e.clientY;
},{passive:true});
window.addEventListener("pointerup",function(){ ptr=null; });
window.addEventListener("pointercancel",function(){ ptr=null; });
Array.prototype.forEach.call(dpadEl.querySelectorAll("button"),function(b){
  var handler=function(ev){ ev.preventDefault(); var p=b.getAttribute("data-dir").split(",");
    turn({x:parseInt(p[0],10),y:parseInt(p[1],10)}); };
  b.addEventListener("pointerdown",handler);
});
document.addEventListener("visibilitychange",function(){
  if(document.hidden&&state==="playing"){ setState("paused"); show("scrPause"); }
});
document.addEventListener("gesturestart",function(e){ e.preventDefault(); });

/* boot */
resize(); refreshHome(); level=LEVELS[0]; buildBg();
lastFrame=performance.now(); requestAnimationFrame(frame);
})();
</script>
</body>
</html>

